+[CmdletBinding()]
+param(
+    [ValidateSet('Audit', 'Backup', 'Restore', 'Repair', 'All')]
+    [string]$Action = 'Audit'
+)
+$ErrorActionPreference = 'Stop'
+$HomePath = [Environment]::GetFolderPath('UserProfile')
+$RoleRoot = $PSScriptRoot
+$BackupRoot = Join-Path $RoleRoot 'backup'
+$InventoryPath = Join-Path $RoleRoot 'SKILL-INVENTORY.md'
+$Sources = @(
+    @{ Name = 'cursor-custom-skills'; Path = Join-Path $HomePath '.cursor\skills'; Kind = 'Skills'; Scope = 'Global user'; Restore = $true },
+    @{ Name = 'cursor-builtin-skills'; Path = Join-Path $HomePath '.cursor\skills-cursor'; Kind = 'Skills'; Scope = 'Cursor managed'; Restore = $false },
+    @{ Name = 'codex-skills'; Path = Join-Path $HomePath '.codex\skills'; Kind = 'Skills'; Scope = 'Global user'; Restore = $true },
+    @{ Name = 'agent-skills'; Path = Join-Path $HomePath '.agents\skills'; Kind = 'Skills'; Scope = 'Cross-framework global'; Restore = $true },
+    @{ Name = 'cursor-rules'; Path = Join-Path $HomePath '.cursor\rules'; Kind = 'Rules'; Scope = 'Global user'; Restore = $true }
+)
+function Get-SkillMetadata {
+    param([string]$Root, [string]$SourceName, [string]$Scope)
+    if (-not (Test-Path $Root)) {
+        return @()
+    }
+    $items = @()
+    Get-ChildItem -Path $Root -Filter 'SKILL.md' -File -Recurse | ForEach-Object {
+        $content = Get-Content -LiteralPath $_.FullName -Raw
+        $nameMatch = [regex]::Match($content, '(?m)^name:\s*["'']?([^"''\r\n]+)')
+        $descriptionMatch = [regex]::Match($content, '(?m)^description:\s*["'']?([^"''\r\n]+)')
+        $name = if ($nameMatch.Success) { $nameMatch.Groups[1].Value.Trim() } else { $_.Directory.Name }
+        $description = if ($descriptionMatch.Success) { $descriptionMatch.Groups[1].Value.Trim() } else { '' }
+        $items += [pscustomobject]@{
+            Name = $name
+            Source = $SourceName
+            Scope = $Scope
+            Path = $_.FullName
+            Description = $description
+        }
+    }
+    return $items
+}
+function Get-CommandStatus {
+    param([string]$Name, [string[]]$VersionArguments = @('--version'))
+    $command = Get-Command $Name -ErrorAction SilentlyContinue
+    if (-not $command) {
+        return [pscustomobject]@{ Name = $Name; Installed = $false; Version = 'missing'; Path = '' }
+    }
+    $version = try { (& $Name @VersionArguments 2>&1 | Select-Object -First 1).ToString().Trim() } catch { 'unknown' }
+    return [pscustomobject]@{ Name = $Name; Installed = $true; Version = $version; Path = $command.Source }
+}
+function Write-Inventory {
+    $skills = @()
+    foreach ($source in $Sources | Where-Object { $_.Kind -eq 'Skills' }) {
+        $skills += Get-SkillMetadata -Root $source.Path -SourceName $source.Name -Scope $source.Scope
+    }
+    $duplicates = $skills | Group-Object Name | Where-Object Count -gt 1 | Sort-Object Name
+    $tools = @(
+        Get-CommandStatus -Name 'graphify'
+        Get-CommandStatus -Name 'graphify-mcp'
+        Get-CommandStatus -Name 'playwright-cli'
+        Get-CommandStatus -Name 'node'
+        Get-CommandStatus -Name 'npm'
+        Get-CommandStatus -Name 'uv'
+        Get-CommandStatus -Name 'git'
+    )
+    $ponytailHooks = Join-Path $HomePath '.cursor\hooks.json'
+    $ponytailState = Join-Path $HomePath '.cursor\.ponytail-active'
+    $lines = [System.Collections.Generic.List[string]]::new()
+    $lines.Add('# Skill / Role inventory')
+    $lines.Add('')
+    $lines.Add("Generated: $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss zzz')")
+    $lines.Add('')
+    $lines.Add('## Summary')
+    $lines.Add('')
+    $lines.Add("- Skills found: $($skills.Count)")
+    $lines.Add("- Unique skill names: $(($skills.Name | Sort-Object -Unique).Count)")
+    $lines.Add("- Duplicate names: $($duplicates.Count)")
+    $lines.Add("- Cursor custom roles/agents: no global `~/.cursor/agents` directory detected by this manager")
+    $lines.Add('')
+    $lines.Add('## Global command-line tools')
+    $lines.Add('')
+    foreach ($tool in $tools) {
+        $state = if ($tool.Installed) { 'OK' } else { 'MISSING' }
+        $lines.Add("- **$($tool.Name)**: $state; $($tool.Version); `$($tool.Path)`")
+    }
+    $lines.Add('')
+    $lines.Add('## Global integrations')
+    $lines.Add('')
+    $lines.Add("- **Ponytail hooks**: $(if (Test-Path $ponytailHooks) { 'installed' } else { 'missing' }) at `$ponytailHooks`")
+    $lines.Add("- **Ponytail mode**: $(if (Test-Path $ponytailState) { (Get-Content $ponytailState -Raw).Trim() } else { 'unknown' })")
+    $lines.Add("- **Graphify cross-framework skill**: $(if (Test-Path (Join-Path $HomePath '.agents\skills\graphify\SKILL.md')) { 'installed' } else { 'missing' })")
+    $lines.Add("- **Graphify Cursor global rule**: $(if (Test-Path (Join-Path $HomePath '.cursor\rules\graphify.mdc')) { 'installed' } else { 'missing' })")
+    $lines.Add('')
+    $lines.Add('## Skills by source')
+    foreach ($group in $skills | Sort-Object Source, Name | Group-Object Source) {
+        $lines.Add('')
+        $lines.Add("### $($group.Name) ($($group.Count))")
+        $lines.Add('')
+        foreach ($skill in $group.Group) {
+            $relativePath = $skill.Path.Replace($HomePath, '~')
+            $lines.Add("- **$($skill.Name)** — $($skill.Scope) — `$relativePath`")
+        }
+    }
+    $lines.Add('')
+    $lines.Add('## Duplicate skill names')
+    $lines.Add('')
+    if ($duplicates.Count -eq 0) {
+        $lines.Add('- None')
+    } else {
+        foreach ($duplicate in $duplicates) {
+            $locations = ($duplicate.Group | ForEach-Object { $_.Path.Replace($HomePath, '~') }) -join '; '
+            $lines.Add("- **$($duplicate.Name)** ($($duplicate.Count)): $locations")
+        }
+    }
+    $lines.Add('')
+    $lines.Add('## Recommended usage for a brand-new project')
+    $lines.Add('')
+    $lines.Add('- Global user skills and rules are available without copying them into the project.')
+    $lines.Add('- Keep project-specific rules in `<project>/.cursor/rules/` or `<project>/AGENTS.md` only when that project needs different behavior.')
+    $lines.Add('- CLI tools such as Graphify and Playwright CLI should be installed once on PATH, not once per project.')
+    $lines.Add('- Ponytail is loaded by global Cursor hooks; do not add its workspace rule at the same time because Ponytail treats those mechanisms as alternatives.')
+    [System.IO.File]::WriteAllLines($InventoryPath, $lines, [System.Text.UTF8Encoding]::new($false))
+    Write-Host "Inventory written: $InventoryPath"
+}
+function Copy-Tree {
+    param([string]$Source, [string]$Destination)
+    if (-not (Test-Path $Source)) {
+        return
+    }
+    if (Test-Path $Destination) {
+        Remove-Item -LiteralPath $Destination -Recurse -Force
+    }
+    New-Item -ItemType Directory -Path $Destination -Force | Out-Null
+    Copy-Item -Path (Join-Path $Source '*') -Destination $Destination -Recurse -Force
+}
+function Backup-Roles {
+    New-Item -ItemType Directory -Path $BackupRoot -Force | Out-Null
+    foreach ($source in $Sources) {
+        Copy-Tree -Source $source.Path -Destination (Join-Path $BackupRoot $source.Name)
+    }
+    $hooksPath = Join-Path $HomePath '.cursor\hooks.json'
+    if (Test-Path $hooksPath) {
+        Copy-Item -LiteralPath $hooksPath -Destination (Join-Path $BackupRoot 'cursor-hooks.json') -Force
+    }
+    $ponytailState = Join-Path $HomePath '.cursor\.ponytail-active'
+    if (Test-Path $ponytailState) {
+        Copy-Item -LiteralPath $ponytailState -Destination (Join-Path $BackupRoot 'ponytail-active.txt') -Force
+    }
+    $manifest = [ordered]@{
+        createdAt = (Get-Date).ToString('o')
+        machine = $env:COMPUTERNAME
+        user = $env:USERNAME
+        sources = $Sources
+        note = 'Backup contains installed skill/rule/hook content, not package caches or CLI executable binaries.'
+    }
+    $manifest | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath (Join-Path $BackupRoot 'manifest.json') -Encoding utf8
+    Write-Host "Backup written: $BackupRoot"
+}
+function Restore-Roles {
+    if (-not (Test-Path (Join-Path $BackupRoot 'manifest.json'))) {
+        throw "Backup manifest not found at $BackupRoot"
+    }
+    foreach ($source in $Sources | Where-Object Restore) {
+        $backupPath = Join-Path $BackupRoot $source.Name
+        if (Test-Path $backupPath) {
+            Copy-Tree -Source $backupPath -Destination $source.Path
+        }
+    }
+    $hooksBackup = Join-Path $BackupRoot 'cursor-hooks.json'
+    if (Test-Path $hooksBackup) {
+        New-Item -ItemType Directory -Path (Join-Path $HomePath '.cursor') -Force | Out-Null
+        Copy-Item -LiteralPath $hooksBackup -Destination (Join-Path $HomePath '.cursor\hooks.json') -Force
+    }
+    Write-Host 'Restorable global skills, rules, and hooks restored.'
+}
+function Ensure-Graphify {
+    if (-not (Get-Command graphify -ErrorAction SilentlyContinue)) {
+        if (-not (Get-Command uv -ErrorAction SilentlyContinue)) {
+            throw 'Graphify is missing and uv is unavailable. Install uv first: https://docs.astral.sh/uv/'
+        }
+        uv tool install --upgrade 'graphifyy[mcp]'
+    } else {
+        uv tool install --upgrade 'graphifyy[mcp]'
+    }
+    graphify install --platform agents
+    $projectRule = Join-Path $RoleRoot '.cursor\rules\graphify.mdc'
+    if (-not (Test-Path $projectRule)) {
+        graphify cursor install
+    }
+    $globalRuleDir = Join-Path $HomePath '.cursor\rules'
+    New-Item -ItemType Directory -Path $globalRuleDir -Force | Out-Null
+    Copy-Item -LiteralPath $projectRule -Destination (Join-Path $globalRuleDir 'graphify.mdc') -Force
+}
+function Ensure-PlaywrightCli {
+    if (-not (Get-Command npm -ErrorAction SilentlyContinue)) {
+        throw 'npm is required to install Playwright CLI.'
+    }
+    npm install -g '@playwright/cli@latest'
+}
+function Ensure-Ponytail {
+    $ponytailPath = Join-Path $HomePath 'tools\ponytail'
+    if (-not (Test-Path (Join-Path $ponytailPath '.git'))) {
+        New-Item -ItemType Directory -Path (Split-Path $ponytailPath -Parent) -Force | Out-Null
+        git clone https://github.com/DietrichGebert/ponytail.git $ponytailPath
+    } else {
+        git -C $ponytailPath pull --ff-only
+    }
+    node (Join-Path $ponytailPath 'scripts\cursor-hooks.js') install
+}
+function Repair-GlobalTools {
+    Ensure-Graphify
+    Ensure-PlaywrightCli
+    Ensure-Ponytail
+    Write-Host 'Global Graphify, Playwright CLI, and Ponytail integrations repaired.'
+}
+switch ($Action) {
+    'Audit' {
+        Write-Inventory
+    }
+    'Backup' {
+        Write-Inventory
+        Backup-Roles
+    }
+    'Restore' {
+        Restore-Roles
+        Write-Inventory
+    }
+    'Repair' {
+        Repair-GlobalTools
+        Write-Inventory
+    }
+    'All' {
+        Repair-GlobalTools
+        Write-Inventory
+        Backup-Roles
+    }
+}
