+[CmdletBinding()]
+param(
+    [ValidateSet('Scan', 'Sync')]
+    [string]$Action = 'Scan',
+    [string]$ScanRoot = 'G:\',
+    [string]$LibraryRoot = (Join-Path $PSScriptRoot 'g-drive-library'),
+    [string]$AgentSkillRoot = (Join-Path ([Environment]::GetFolderPath('UserProfile')) '.agents\skills'),
+    [string]$CursorSkillRoot = (Join-Path ([Environment]::GetFolderPath('UserProfile')) '.cursor\skills')
+)
+$ErrorActionPreference = 'Stop'
+$ExcludedPathPattern = '(?i)[\\/](node_modules|vendor|packages|bin|obj|dist|build|\.git|\.svn|\.hg|\$RECYCLE\.BIN|System Volume Information|\.role[\\/]backup|\.role[\\/]g-drive-library|\.codex[\\/](\.tmp|plugins|visualizations)|\.build-cache|AppData|Temp)[\\/]'
+$SkillRootPattern = '(?i)[\\/](\.agents[\\/]skills|\.cursor[\\/]skills|\.claude[\\/]skills|\.codex[\\/]skills)[\\/]'
+$RuleRootPattern = '(?i)[\\/]\.cursor[\\/]rules[\\/]'
+function Get-SafeName {
+    param([string]$Value)
+    $safe = $Value -replace '[^a-zA-Z0-9._-]', '-'
+    return $safe.Trim('-')
+}
+function Get-SkillName {
+    param([string]$SkillFile)
+    $content = Get-Content -LiteralPath $SkillFile -Raw
+    $match = [regex]::Match($content, '(?m)^name:\s*["'']?([^"''\r\n]+)')
+    if ($match.Success) {
+        return $match.Groups[1].Value.Trim()
+    }
+    return (Split-Path (Split-Path $SkillFile -Parent) -Leaf)
+}
+function Get-DirectoryHash {
+    param([string]$Directory)
+    $sha = [System.Security.Cryptography.SHA256]::Create()
+    try {
+        $builder = [System.Text.StringBuilder]::new()
+        Get-ChildItem -LiteralPath $Directory -File -Recurse -ErrorAction SilentlyContinue |
+            Sort-Object FullName |
+            ForEach-Object {
+                $relative = $_.FullName.Substring($Directory.Length).TrimStart('\', '/')
+                $fileHash = (Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash
+                [void]$builder.AppendLine("$relative|$fileHash")
+            }
+        $bytes = [System.Text.Encoding]::UTF8.GetBytes($builder.ToString())
+        return ([System.BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-', '').ToLowerInvariant()
+    } finally {
+        $sha.Dispose()
+    }
+}
+function Copy-Directory {
+    param([string]$Source, [string]$Destination)
+    if (Test-Path $Destination) {
+        Remove-Item -LiteralPath $Destination -Recurse -Force
+    }
+    New-Item -ItemType Directory -Path $Destination -Force | Out-Null
+    Get-ChildItem -LiteralPath $Source -Force -ErrorAction SilentlyContinue | Copy-Item -Destination $Destination -Recurse -Force
+}
+function Get-SourcePriority {
+    param([string]$Path)
+    if ($Path -match '(?i)[\\/]\.agents[\\/]skills[\\/]') {
+        return 1
+    }
+    if ($Path -match '(?i)[\\/]\.cursor[\\/]skills[\\/]') {
+        return 2
+    }
+    if ($Path -match '(?i)[\\/]\.claude[\\/]skills[\\/]') {
+        return 3
+    }
+    return 4
+}
+function Find-Skills {
+    $files = Get-ChildItem -Path $ScanRoot -Filter 'SKILL.md' -File -Recurse -Force -ErrorAction SilentlyContinue
+    $results = @()
+    foreach ($file in $files) {
+        if ($file.FullName -match $ExcludedPathPattern -or $file.FullName -notmatch $SkillRootPattern) {
+            continue
+        }
+        $directory = $file.Directory.FullName
+        $results += [pscustomobject]@{
+            Name = Get-SkillName -SkillFile $file.FullName
+            Hash = Get-DirectoryHash -Directory $directory
+            Directory = $directory
+            SkillFile = $file.FullName
+            Priority = Get-SourcePriority -Path $file.FullName
+        }
+    }
+    return @($results)
+}
+function Find-Rules {
+    $files = Get-ChildItem -Path $ScanRoot -Filter '*.mdc' -File -Recurse -Force -ErrorAction SilentlyContinue
+    return @($files | Where-Object { $_.FullName -notmatch $ExcludedPathPattern -and $_.FullName -match $RuleRootPattern })
+}
+function Write-Library {
+    param([array]$Skills, [array]$Rules)
+    if (Test-Path $LibraryRoot) {
+        Remove-Item -LiteralPath $LibraryRoot -Recurse -Force
+    }
+    $skillLibrary = Join-Path $LibraryRoot 'skills'
+    $ruleLibrary = Join-Path $LibraryRoot 'rules'
+    New-Item -ItemType Directory -Path $skillLibrary, $ruleLibrary -Force | Out-Null
+    $skillEntries = @()
+    foreach ($skill in $Skills) {
+        $safeName = Get-SafeName -Value $skill.Name
+        $shortHash = $skill.Hash.Substring(0, 12)
+        $destination = Join-Path $skillLibrary "$safeName\$shortHash"
+        if (-not (Test-Path $destination)) {
+            Copy-Directory -Source $skill.Directory -Destination $destination
+        }
+        $skillEntries += [ordered]@{
+            name = $skill.Name
+            hash = $skill.Hash
+            source = $skill.Directory
+            library = $destination
+            priority = $skill.Priority
+        }
+    }
+    $ruleEntries = @()
+    foreach ($rule in $Rules) {
+        $hash = (Get-FileHash -LiteralPath $rule.FullName -Algorithm SHA256).Hash.ToLowerInvariant()
+        $safeBase = Get-SafeName -Value $rule.BaseName
+        $destination = Join-Path $ruleLibrary "$safeBase-$($hash.Substring(0, 12)).mdc"
+        if (-not (Test-Path $destination)) {
+            Copy-Item -LiteralPath $rule.FullName -Destination $destination -Force
+        }
+        $ruleEntries += [ordered]@{
+            name = $rule.Name
+            hash = $hash
+            source = $rule.FullName
+            library = $destination
+        }
+    }
+    $groups = @($Skills | Group-Object Name)
+    $conflicts = @($groups | Where-Object { ($_.Group.Hash | Sort-Object -Unique).Count -gt 1 })
+    $manifest = [ordered]@{
+        generatedAt = (Get-Date).ToString('o')
+        scanRoot = $ScanRoot
+        exclusions = $ExcludedPathPattern
+        summary = [ordered]@{
+            skillCandidates = $Skills.Count
+            uniqueSkillNames = $groups.Count
+            uniqueSkillContents = @($Skills | Group-Object Hash).Count
+            conflictingSkillNames = $conflicts.Count
+            projectRules = $Rules.Count
+        }
+        skills = $skillEntries
+        rules = $ruleEntries
+    }
+    $manifest | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath (Join-Path $LibraryRoot 'manifest.json') -Encoding utf8
+    return $manifest
+}
+function Install-Skills {
+    param([array]$Skills)
+    New-Item -ItemType Directory -Path $AgentSkillRoot, $CursorSkillRoot -Force | Out-Null
+    $installed = @()
+    foreach ($group in $Skills | Group-Object Name) {
+        $variants = @($group.Group | Sort-Object Priority, Directory)
+        $selected = $variants[0]
+        $safeName = Get-SafeName -Value $group.Name
+        foreach ($targetRoot in @($AgentSkillRoot, $CursorSkillRoot)) {
+            $destination = Join-Path $targetRoot $safeName
+            if (Test-Path (Join-Path $destination 'SKILL.md')) {
+                $existingHash = Get-DirectoryHash -Directory $destination
+                if ($existingHash -eq $selected.Hash) {
+                    continue
+                }
+                $existingBackup = Join-Path $LibraryRoot "pre-sync-global\$((Split-Path $targetRoot -Leaf))\$safeName\$($existingHash.Substring(0, 12))"
+                if (-not (Test-Path $existingBackup)) {
+                    Copy-Directory -Source $destination -Destination $existingBackup
+                }
+            }
+            Copy-Directory -Source $selected.Directory -Destination $destination
+        }
+        $installed += [pscustomobject]@{
+            Name = $group.Name
+            SelectedSource = $selected.Directory
+            Variants = @($variants.Hash | Sort-Object -Unique).Count
+        }
+    }
+    return $installed
+}
+function Write-Report {
+    param([object]$Manifest, [array]$Installed)
+    $reportPath = Join-Path $PSScriptRoot 'G-DRIVE-SKILLS.md'
+    $lines = [System.Collections.Generic.List[string]]::new()
+    $lines.Add('# G Drive skill collection')
+    $lines.Add('')
+    $lines.Add("Generated: $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss zzz')")
+    $lines.Add('')
+    $lines.Add("Skill candidates: $($Manifest.summary.skillCandidates)")
+    $lines.Add("Unique names: $($Manifest.summary.uniqueSkillNames)")
+    $lines.Add("Unique contents: $($Manifest.summary.uniqueSkillContents)")
+    $lines.Add("Conflicting names: $($Manifest.summary.conflictingSkillNames)")
+    $lines.Add("Project rules archived: $($Manifest.summary.projectRules)")
+    if ($Installed) {
+        $lines.Add("Global skills selected: $($Installed.Count)")
+    }
+    $lines.Add('')
+    $lines.Add('## Conflict policy')
+    $lines.Add('')
+    $lines.Add('- Every distinct version is kept in g-drive-library.')
+    $lines.Add('- Global selection priority is .agents/skills, then .cursor/skills, then .claude/skills, then .codex/skills.')
+    $lines.Add('- Existing global content is backed up under g-drive-library/pre-sync-global before replacement.')
+    $lines.Add('- Project rules are archived only and are not enabled globally.')
+    $lines.Add('')
+    $lines.Add('## Skills')
+    $lines.Add('')
+    foreach ($group in $Manifest.skills | Group-Object name | Sort-Object Name) {
+        $hashCount = @($group.Group.hash | Sort-Object -Unique).Count
+        $lines.Add("- **$($group.Name)**: $($group.Count) source(s), $hashCount content version(s)")
+    }
+    [System.IO.File]::WriteAllLines($reportPath, $lines, [System.Text.UTF8Encoding]::new($false))
+    Write-Host "Report written: $reportPath"
+}
+$skills = Find-Skills
+$rules = Find-Rules
+$manifest = Write-Library -Skills $skills -Rules $rules
+$installed = @()
+if ($Action -eq 'Sync') {
